; ============================================================
; Random (16 bit xorshift 7,9,8 - period 65535)
; ============================================================

;## ntc_rnd_seed
ntc_rnd_seed:	dw 1

;## kw_rndl ntc_rnd_seed ntc_div
;kw_rndl, <literal>, <destvar>
kw_rndl:
			pop de
ntc_rnd:
			ld hl, (ntc_rnd_seed)
			ld a, h
			rra
			ld a, l
			rra
			xor h
			ld h, a
			ld a, l
			rra
			ld a, h
			rra
			xor l
			ld l, a
			xor h
			ld h, a
			ld (ntc_rnd_seed), hl
			bit 7, d
			jr nz, ntc_rnd_zero
			ld a, d
			or e
			jr z, ntc_rnd_zero
			ld a, 1
			ld (ntc_mode), a
			res 7, h
			jp ntc_div
ntc_rnd_zero:
			ld hl, 0
			jp ntc_div_store

;## kw_seedv ntc_rnd_seed kw_seedl
;kw_seedv, <var>  - RANDOMIZE var (0 becomes 1)
kw_seedv:
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ex de, hl
			jr ntc_seed

;## kw_seedl ntc_rnd_seed
;kw_seedl, <literal>
kw_seedl:
			pop hl
ntc_seed:
			ld a, h
			or l
			jr nz, ntc_seed_ok
			inc l
ntc_seed_ok:
			ld (ntc_rnd_seed), hl
			ret

; ============================================================
; Strings: 0 terminated. A string variable or temp has its capacity
; (1 .. 255 chars) in the byte before it: [cap][text...][0]. Array
; elements have no capacity byte (the caller gives the element size).
; Functions that build a string write into a temp, so they cut at
; NTC_STRMAX (the longest string in the program, set by the compiler);
; kw_strcpy / kw_strcat / input cut at the destination's capacity.
; ============================================================

;## kw_strcpy
;kw_strcpy, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcpy:
			pop de
			pop hl
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcpy_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcpy_loop
			xor a
			ld (de), a
			ret

;## kw_strcat
;kw_strcat, <destaddr>, <srcaddr>  - cut at the destination's capacity byte
kw_strcat:
			pop de
			dec de
			ld a, (de)
			ld b, a
			inc de
ntc_strcat_end:
			ld a, (de)
			or a
			jr z, ntc_strcat_copy
			inc de
			djnz ntc_strcat_end
			pop hl
			ret
ntc_strcat_copy:
			pop hl
ntc_strcat_loop:
			ld a, (hl)
			ld (de), a
			or a
			ret z
			inc hl
			inc de
			djnz ntc_strcat_loop
			xor a
			ld (de), a
			ret

;## kw_strlen
;kw_strlen, <straddr>, <destvar>
kw_strlen:
			pop hl
			ld bc, 0
ntc_strlen_loop:
			ld a, (hl)
			or a
			jr z, ntc_strlen_done
			inc hl
			inc c
			jr ntc_strlen_loop
ntc_strlen_done:
			pop hl
			ld (hl), c
			inc hl
			ld (hl), b
			ret

;## kw_strcmpeq
;kw_strcmpeq, <addr1>, <addr2>  - Z if equal
kw_strcmpeq:
			pop de
			pop hl
ntc_streq_loop:
			ld a, (de)
			cp (hl)
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr ntc_streq_loop

;## ntc_printbuf ntc_data ntc_plat_screen
; print the 0 terminated ASCII text at (ntc_sptr), then ret (thread)
ntc_printbuf:
			ld hl, (ntc_sptr)
			ld a, (hl)
			or a
			ret z
			inc hl
			ld (ntc_sptr), hl
			ld ix, ntc_printbuf
			jp ntc_plat_putc

;## kw_printstrvar ntc_printbuf
;kw_printstrvar, <straddr>
kw_printstrvar:
			pop hl
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## ntc_itoa ntc_data
; HL = signed value, DE = buffer: writes the digits and a 0 (DE ends on
; the 0). jp (ix) back. Uses A, BC, IY.
ntc_itoa:
			bit 7, h
			jr z, ntc_ia_pos
			ld a, '-'
			ld (de), a
			inc de
			xor a
			sub l
			ld l, a
			sbc a, a
			sub h
			ld h, a
ntc_ia_pos:
			xor a
			ld (ntc_lead), a
			ld iy, ntc_pow10
ntc_ia_pow:
			ld c, (iy+0)
			ld b, (iy+1)
			ld a, b
			or c
			jr z, ntc_ia_last
			ld a, '0' - 1
ntc_ia_sub:
			inc a
			and a
			sbc hl, bc
			jr nc, ntc_ia_sub
			add hl, bc
			cp '0'
			jr nz, ntc_ia_out
			ld b, a
			ld a, (ntc_lead)
			or a
			ld a, b
			jr z, ntc_ia_skip
ntc_ia_out:
			ld (de), a
			inc de
			ld a, 1
			ld (ntc_lead), a
ntc_ia_skip:
			inc iy
			inc iy
			jr ntc_ia_pow
ntc_ia_last:
			ld a, l
			add a, '0'
			ld (de), a
			inc de
			xor a
			ld (de), a
			jp (ix)
ntc_pow10:		dw 10000, 1000, 100, 10, 0

;## kw_printint ntc_printbuf ntc_itoa
;kw_printint, <var>  - signed decimal
kw_printint:
			pop hl
			ld a, (hl)
			inc hl
			ld h, (hl)
			ld l, a
			ld de, ntc_numbuf
			ld ix, ntc_pi_done
			jp ntc_itoa
ntc_pi_done:
			ld hl, ntc_numbuf
			ld (ntc_sptr), hl
			jp ntc_printbuf

;## kw_printnl ntc_data ntc_plat_screen
;kw_printnl
kw_printnl:
			ld ix, ntc_next
			jp ntc_plat_newline

;## kw_model ntc_data ntc_plat_screen
;kw_model, <literal>  - 0, 1 or 2, clears the screen
kw_model:
			pop hl
			ld a, l
			ld ix, ntc_next
			jp ntc_plat_mode

;## kw_ticks ntc_data ntc_plat_ticks
;kw_ticks, <destvar>  - tick count from the platform (CPC: interrupts, 300 a second,
;  only moving in normal mode)
kw_ticks:
			pop hl
			ld (ntc_ivar), hl
			ld ix, ntc_tk_got
			jp ntc_plat_ticks
ntc_tk_got:
			ex de, hl
			ld hl, (ntc_ivar)
			ld (hl), e
			inc hl
			ld (hl), d
			ret

; ============================================================
; String functions. Numbers are passed as the address of a word
; (a literal goes in as lit_n, a dw in the data). Results go to a
; string buffer (41 bytes). Dest may be the same as the source.
; ============================================================

;## ntc_getn ntc_data
; BC = address of a word: A = its value limited to 0..255
; (below 0 = 0, above 255 = 255). jp (ix) back. Keeps DE, HL.
ntc_getn:
			ld a, (bc)
			ld (ntc_gnlo), a
			inc bc
			ld a, (bc)
			or a
			jp m, ntc_gn_zero
			jr nz, ntc_gn_max
			ld a, (ntc_gnlo)
			jp (ix)
ntc_gn_zero:
			xor a
			jp (ix)
ntc_gn_max:
			ld a, 255
			jp (ix)

;## kw_strleft ntc_getn
;kw_strleft, <dest>, <src>, <nvar>  - Left$(src, n)
kw_strleft:
			pop de
			pop hl
			pop bc
			ld ix, ntc_sl_n
			jp ntc_getn
ntc_sl_n:
			ld b, a
; copy up to B chars from HL to DE, then the 0
ntc_strncpy:
			inc b
ntc_sn_loop:
			dec b
			jr z, ntc_sn_end
			ld a, (hl)
			or a
			jr z, ntc_sn_end
			ld (de), a
			inc hl
			inc de
			jr ntc_sn_loop
ntc_sn_end:
			xor a
			ld (de), a
			ret

;## kw_strright ntc_getn kw_strleft
;kw_strright, <dest>, <src>, <nvar>  - Right$(src, n)
kw_strright:
			pop de
			pop hl
			pop bc
			ld ix, ntc_sr_n
			jp ntc_getn
ntc_sr_n:
			ld c, a
			ld (ntc_sptr), hl
			ld b, 0
ntc_sr_len:
			ld a, (hl)
			or a
			jr z, ntc_sr_got
			inc hl
			inc b
			jr ntc_sr_len
ntc_sr_got:
			ld a, b
			sub c
			jr nc, ntc_sr_skip
			xor a
ntc_sr_skip:
			ld hl, (ntc_sptr)
			ld c, a
			ld b, 0
			add hl, bc
			ld b, 255
			jp ntc_strncpy

;## kw_pow
;kw_pow, <basevar>, <expvar>, <destvar>  - base ^ exp (Integer, low 16 bits; exp < 0 gives 0)
kw_pow:
			pop hl
			ld c, (hl)
			inc hl
			ld b, (hl)
			pop hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld hl, 1
			bit 7, d
			jr z, ntc_pw_go
			ld hl, 0
			jr ntc_pw_st
ntc_pw_go:
			ld a, d
			or e
			jr z, ntc_pw_st
			ld (ntc_pwe), de
			ex de, hl
			ld hl, 0
			ld a, 16
ntc_pw_mul:
			add hl, hl
			sla e
			rl d
			jr nc, ntc_pw_sk
			add hl, bc
ntc_pw_sk:
			dec a
			jr nz, ntc_pw_mul
			ld de, (ntc_pwe)
			dec de
			jr ntc_pw_go
ntc_pw_st:
			ex de, hl
			pop hl
			ld (hl), e
			inc hl
			ld (hl), d
			ret
ntc_pwe:		dw 0

;## kw_strmid ntc_getn kw_strleft
;kw_strmid, <dest>, <src>, <startvar>, <lenvar>  - Mid$(src, start, len)
kw_strmid:
			pop de
			pop hl
			pop bc
			ld ix, ntc_sm_s
			jp ntc_getn
ntc_sm_s:
			or a
			jr z, ntc_sm_s1
			dec a
ntc_sm_s1:
			ld b, a
			inc b
ntc_sm_skip:
			dec b
			jr z, ntc_sm_len
			ld a, (hl)
			or a
			jr z, ntc_sm_len
			inc hl
			jr ntc_sm_skip
ntc_sm_len:
			pop bc
			ld ix, ntc_sm_n
			jp ntc_getn
ntc_sm_n:
			ld b, a
			jp ntc_strncpy

;## kw_strrtrim ntc_data
;kw_strrtrim, <dest>, <src>  - RTrim$
kw_strrtrim:
			pop de
			pop hl
			ld (ntc_sptr), de
ntc_rt_copy:
			ld a, (hl)
			ld (de), a
			or a
			jr z, ntc_rt_back
			inc hl
			inc de
			jr ntc_rt_copy
ntc_rt_back:
			ld hl, (ntc_sptr)
			ex de, hl
ntc_rt_loop:
			or a
			sbc hl, de
			add hl, de
			ret z
			dec hl
			ld a, (hl)
			cp ' '
			ret nz
			ld (hl), 0
			jr ntc_rt_loop

;## kw_strtrim kw_strrtrim
;kw_strtrim, <dest>, <src>  - Trim$
kw_strtrim:
			pop de
			pop hl
ntc_tr_skip:
			ld a, (hl)
			cp ' '
			jr nz, ntc_tr_go
			inc hl
			jr ntc_tr_skip
ntc_tr_go:
			ld (ntc_sptr), de
			jp ntc_rt_copy

;## kw_strasc
;kw_strasc, <src>, <destvar>  - Asc(src), 0 if empty
kw_strasc:
			pop hl
			ld a, (hl)
			pop hl
			ld (hl), a
			inc hl
			ld (hl), 0
			ret

;## ntc_buf2k
; ntc_buf - a buffer shared by the classes that need one: FileSystem's
; CAS IN / OUT OPEN buffer (CPC firmware: 2K) and Memory.Copy's page to page
; copy (that much at a time). NTC_BUFSIZE (Option Buffer): 2048 unless set
ntc_buf:		ds NTC_BUFSIZE

;## ntc_romdisc ntc_data ntc_plat_romsel @shared @ramonly
; ------------------------------------------------------------
; ntc_romdisc - ROMDISC: read-only files kept in ROMs, the FileSystem's
; volume R (cpc, cpcmin, cpcfw). A disc is a set of ROMs NTCDISC.ROM,
; NTCDISC2.ROM ... (made by ntcRomDisc in ntc_compiler.js) in any slots
; 0-31: background ROMs whose names are followed by the block
;   "NTC", 2, "ROMDISC", 0, dw stamp, db place, db ROMs, dw directory (ROM 0)
; ROM 0 has the directory at #C040: entries of RD_ENTRY bytes, read until
; one whose flags have bit 7 set (the end):
;   +0 name (8, spaces after), +8 extension (3), +11 flags (bit 0
;   compressed - none are yet), +12 its ROM (place in the set), +13 its
;   address (dw), +15 its length (3 bytes)
; A file's bytes run on from its address; past #FFFF they go on at RD_DATA
; of the next ROM. Reading selects the disc's ROM (ntc_plat_romsel: rd_sel /
; rd_unsel), so this runs from RAM: it is not in the keyword ROM (@ramonly).
; Routines run on the real stack (rd_go on cpc, the FileSystem's fs_go on
; cpcmin / cpcfw); arguments in rd_a1 .. rd_a3, a string / Long result at
; (rd_res); HL = the result or a status. One file open: handle 2.
; ------------------------------------------------------------
RD_DATA		equ #C040		; directory (ROM 0) and file data start
RD_ENTRY	equ 18
RD_HANDLE	equ 2
RD_NOTSUP	equ -1
RD_NOTFOUND	equ -2
RD_BADNAME	equ -4
RD_NOHANDLE	equ -5
RD_BADHANDLE	equ -6
RD_EOF		equ -7
RD_TOOBIG	equ -8
rd_a1:			dw 0
rd_a2:			dw 0
rd_a3:			dw 0
rd_res:			dw 0
rd_sp:			dw 0
rd_six:			dw 0
rd_siy:			dw 0
rd_nostore:		db 0
rd_state:		db 0			; 0 = not looked for yet, 1 = there, 2 = none
rd_want:		db 0
rd_n:			db 0			; ROMs in the disc
rd_stamp:		dw 0
rd_dir:			dw 0			; the directory (ROM 0)
rd_slots:		ds 8			; each ROM's slot
rd_name:		ds 11			; a name as the directory has it
rd_ent:			ds RD_ENTRY		; the entry found
rd_isopen:		db 0			; 1 = a file open (handle 2)
rd_rom:			db 0			; reading: the ROM, the address, the bytes left
rd_addr:		dw 0
rd_left:		ds 3
rd_cnt:			dw 0
rd_dst:			dw 0
rd_cap:			db 0
rd_sig:			db "NTC", 2, "ROMDISC", 0
rd_sige:

; rd_go / rd_go0 - (cpc) HL = the routine: run on the real stack, its HL
; stored at (rd_res) (rd_go0: not stored - the routine writes its result)
rd_go0:
			ld a, 1
			jr rd_gostart
rd_go:
			xor a
rd_gostart:
			ld (rd_nostore), a
			ld (rd_sp), sp
			ld sp, (ntc_csp)
			ld (rd_six), ix
			ld (rd_siy), iy
			ld a, (ntc_nmode)
			or a
			jr z, rd_g_call
			ei
rd_g_call:
			call rd_jphl
			di
			ld ix, (rd_six)
			ld iy, (rd_siy)
			ld a, (rd_nostore)
			or a
			jr nz, rd_g_end
			ex de, hl
			ld hl, (rd_res)
			ld (hl), e
			inc hl
			ld (hl), d
rd_g_end:
			ld sp, (rd_sp)
			ret
rd_jphl:
			jp (hl)

; rd_mount - is a disc there? (looked for once). Z = yes
rd_mount:
			ld a, (rd_state)
			cp 1
			ret z
			or a
			jr nz, rd_mt_no
			xor a
			ld (rd_want), a
			call rd_scan
			jr c, rd_mt_none
			ld (rd_slots), a
			ld a, 1
rd_mt_more:
			ld (rd_want), a
			ld hl, rd_n
			cp (hl)
			jr nc, rd_mt_ok
			call rd_scan
			jr c, rd_mt_none		; a part missing: no disc
			ld b, a
			ld a, (rd_want)
			ld e, a
			ld d, 0
			ld hl, rd_slots
			add hl, de
			ld (hl), b
			inc a
			jr rd_mt_more
rd_mt_ok:
			ld a, 1
			ld (rd_state), a
			cp a					; Z
			ret
rd_mt_none:
			ld a, 2
			ld (rd_state), a
rd_mt_no:
			or 1					; NZ
			ret

; rd_scan - the disc ROM rd_want (0: any stamp; the others: ROM 0's stamp).
; NC: A = its slot (ROM 0: rd_n, rd_stamp, rd_dir set). C: not there
rd_scan:
			ld c, 0
rd_sc_next:
			push bc
			ld a, c
			call rd_sel
			call rd_sc_try
			call rd_unsel
			pop bc
			jr nc, rd_sc_got
			inc c
			ld a, c
			cp 32
			jr c, rd_sc_next
			scf
			ret
rd_sc_got:
			ld a, c
			ret
rd_sc_try:							; (the ROM is in) NC = it is the one
			ld a, (#C000)
			cp 1					; a background ROM
			jr nz, rd_sc_not
			ld hl, (#C004)			; its names
			ld a, h
			cp #C0
			jr c, rd_sc_not
rd_sc_name:
			ld a, (hl)
			inc hl
			or a
			jr nz, rd_sc_name
			ld de, rd_sig
			ld b, rd_sige - rd_sig
rd_sc_cmp:
			ld a, (de)
			cp (hl)
			jr nz, rd_sc_not
			inc de
			inc hl
			djnz rd_sc_cmp
			ld e, (hl)
			inc hl
			ld d, (hl)				; DE = its stamp
			inc hl
			ld a, (rd_want)
			cp (hl)
			jr nz, rd_sc_not
			inc hl
			or a
			jr nz, rd_sc_stamp
			ld (rd_stamp), de		; ROM 0: the disc's stamp, ROMs, directory
			ld a, (hl)
			ld (rd_n), a
			inc hl
			ld e, (hl)
			inc hl
			ld d, (hl)
			ld (rd_dir), de
			or a
			ret
rd_sc_stamp:
			ld hl, (rd_stamp)
			or a
			sbc hl, de
			ret z					; (NC)
rd_sc_not:
			scf
			ret

; rd_mkname - HL = a name ("NAME.EXT", "R:NAME.EXT"): rd_name. NC, or C = not
; a name (empty, more than 8.3)
rd_mkname:
			push hl
			ld hl, rd_name
			ld b, 11
rd_mk_sp:
			ld (hl), ' '
			inc hl
			djnz rd_mk_sp
			pop hl
			inc hl
			ld a, (hl)
			dec hl
			cp ':'
			jr nz, rd_mk_go
			inc hl					; past "R:"
			inc hl
rd_mk_go:
			ld de, rd_name
			ld b, 9					; up to 8 letters, then . or the end
			ld a, (hl)
			or a
			jr z, rd_mk_bad
rd_mk_lp:
			ld a, (hl)
			or a
			ret z					; (NC)
			inc hl
			cp '.'
			jr z, rd_mk_ext
			dec b
			jr z, rd_mk_bad
			call rd_up
			ld (de), a
			inc de
			jr rd_mk_lp
rd_mk_ext:
			ld de, rd_name + 8
			ld b, 4
rd_mk_elp:
			ld a, (hl)
			or a
			ret z
			inc hl
			dec b
			jr z, rd_mk_bad
			cp '.'
			jr z, rd_mk_bad
			call rd_up
			ld (de), a
			inc de
			jr rd_mk_elp
rd_mk_bad:
			scf
			ret
rd_up:
			cp 'a'
			ret c
			cp 'z' + 1
			ret nc
			sub 32
			ret

; rd_find - rd_a1 = a name: its entry into rd_ent. NC, or C with HL = the status
rd_find:
			call rd_mount
			ld hl, RD_NOTFOUND
			scf
			ret nz
			ld hl, (rd_a1)
			call rd_mkname
			ld hl, RD_BADNAME
			ret c
			ld a, (rd_slots)
			call rd_sel
			ld hl, (rd_dir)
rd_fd_lp:
			push hl
			ld de, 11
			add hl, de
			bit 7, (hl)				; the end
			pop hl
			jr nz, rd_fd_none
			push hl
			ld de, rd_name
			ld b, 11
rd_fd_cmp:
			ld a, (de)
			cp (hl)
			jr nz, rd_fd_nx
			inc de
			inc hl
			djnz rd_fd_cmp
			pop hl
			ld de, rd_ent
			ld bc, RD_ENTRY
			ldir
			call rd_unsel
			or a					; NC
			ret
rd_fd_nx:
			pop hl
			ld de, RD_ENTRY
			add hl, de
			jr rd_fd_lp
rd_fd_none:
			call rd_unsel
			ld hl, RD_NOTFOUND
			scf
			ret

; rd_start - reading from the start of rd_ent's file (rd_rom, rd_addr, rd_left)
rd_start:
			ld hl, rd_ent + 12
			ld de, rd_rom
			ld bc, 6
			ldir
			ret

; rd_copy - BC bytes (no more than are left) to DE: on from rd_rom / rd_addr
rd_copy:
			ld (rd_cnt), bc
			ld (rd_dst), de
rd_cp_lp:
			ld hl, (rd_cnt)
			ld a, h
			or l
			ret z
			ld hl, (rd_addr)		; this ROM's part: up to #FFFF
			ex de, hl
			ld hl, 0
			or a
			sbc hl, de				; HL = #10000 - address
			ld de, (rd_cnt)
			or a
			sbc hl, de
			jr nc, rd_cp_all
			add hl, de				; (only what this ROM has)
			ld b, h
			ld c, l
			jr rd_cp_do
rd_cp_all:
			ld b, d
			ld c, e
rd_cp_do:
			push bc
			call rd_romslot
			call rd_sel
			pop bc
			push bc
			ld hl, (rd_addr)
			ld de, (rd_dst)
			ldir
			ld (rd_dst), de
			call rd_unsel
			pop bc
			ld hl, (rd_cnt)
			or a
			sbc hl, bc
			ld (rd_cnt), hl
			call rd_adv
			jr rd_cp_lp

; rd_adv - BC bytes read: on in the file (the next ROM past #FFFF), fewer left
rd_adv:
			ld hl, (rd_addr)
			add hl, bc
			jr nc, rd_av_same
			ld a, h
			or l
			jr nz, rd_av_same
			ld hl, rd_rom
			inc (hl)
			ld hl, RD_DATA
rd_av_same:
			ld (rd_addr), hl
			ld hl, (rd_left)
			or a
			sbc hl, bc
			ld (rd_left), hl
			ret nc
			ld hl, rd_left + 2
			dec (hl)
			ret

; rd_romslot - A = the slot of rd_rom
rd_romslot:
			ld a, (rd_rom)
			ld e, a
			ld d, 0
			ld hl, rd_slots
			add hl, de
			ld a, (hl)
			ret

; rd_getb - the next byte of the open file: A, NC; C = the end
rd_getb:
			ld hl, (rd_left)
			ld a, h
			or l
			ld hl, rd_left + 2
			or (hl)
			scf
			ret z
			call rd_romslot
			call rd_sel
			ld hl, (rd_addr)
			ld a, (hl)
			push af
			call rd_unsel
			ld bc, 1
			call rd_adv
			pop af
			or a					; NC
			ret

; rd_hchk - rd_a1 must be handle 2, open: else (from the routine) BadHandle
rd_hchk:
			ld hl, (rd_a1)
			ld de, -RD_HANDLE
			add hl, de
			ld a, h
			or l
			jr nz, rd_hc_bad
			ld a, (rd_isopen)
			or a
			ret nz
rd_hc_bad:
			pop hl					; (out of the routine)
			ld hl, RD_BADHANDLE
			ret

; Load(name, addr, maxlen): its length, or a status (TooBig: nothing loaded)
rd_load:
			call rd_find
			ret c
			ld a, (rd_ent + 17)		; more than 65535, or more than maxlen
			or a
			ld hl, RD_TOOBIG
			ret nz
			ld de, (rd_ent + 15)
			ld hl, (rd_a3)
			or a
			sbc hl, de
			ld hl, RD_TOOBIG
			ret c
			call rd_start
			ld bc, (rd_ent + 15)
			ld de, (rd_a2)
			call rd_copy
			ld hl, (rd_ent + 15)
			ret

; Open(name, mode): handle 2, or a status (only ForRead: the disc is read only)
rd_open:
			ld a, (rd_isopen)
			or a
			ld hl, RD_NOHANDLE
			ret nz
			ld hl, (rd_a2)
			ld a, l
			cp 4				; ForReadRaw: the same (a ROMDISC file is read to its length)
			jr nz, rd_op_m
			ld l, 1
rd_op_m:
			dec hl
			ld a, h
			or l
			ld hl, RD_NOTSUP
			ret nz
			call rd_find
			ret c
			call rd_start
			ld a, 1
			ld (rd_isopen), a
			ld hl, RD_HANDLE
			ret

; Close(h): OK or BadHandle
rd_close:
			call rd_hchk
			xor a
			ld (rd_isopen), a
			ld hl, 0
			ret

; ReadByte(h): 0-255, EndOfFile, BadHandle
rd_readb:
			call rd_hchk
			call rd_getb
			ld hl, RD_EOF
			ret c
			ld l, a
			ld h, 0
			ret

; Read(h, addr, count): bytes read (fewer at the end)
rd_read:
			call rd_hchk
			ld hl, (rd_a3)
			bit 7, h
			jr z, rd_rd_pos
			ld hl, 0
rd_rd_pos:
			ld a, (rd_left + 2)		; no more than are left
			or a
			jr nz, rd_rd_go
			ld de, (rd_left)
			push hl
			or a
			sbc hl, de
			pop hl
			jr c, rd_rd_go
			ex de, hl
rd_rd_go:
			push hl
			ld b, h
			ld c, l
			ld de, (rd_a2)
			call rd_copy
			pop hl
			ret

; Eof(h): True when nothing is left (or h is not the open file)
rd_eof:
			ld hl, (rd_a1)
			ld de, -RD_HANDLE
			add hl, de
			ld a, h
			or l
			jr nz, rd_ef_yes
			ld a, (rd_isopen)
			or a
			jr z, rd_ef_yes
			ld hl, (rd_left)
			ld a, h
			or l
			ld hl, rd_left + 2
			or (hl)
			ld hl, 0
			ret nz
rd_ef_yes:
			ld hl, -1
			ret

; ReadLine(h): the next line (up to LF; CR dropped) into the string at (rd_res)
rd_readln:
			ld hl, (rd_res)
			ld (hl), 0
			dec hl
			ld a, (hl)
			ld (rd_cap), a
			inc hl
			ld (rd_dst), hl
			call rd_hchk
rd_rl_lp:
			call rd_getb
			jr c, rd_rl_end
			cp 10
			jr z, rd_rl_end
			cp 13
			jr z, rd_rl_lp
			ld c, a
			ld a, (rd_cap)
			or a
			jr z, rd_rl_lp			; full: the rest of the line is dropped
			dec a
			ld (rd_cap), a
			ld hl, (rd_dst)
			ld (hl), c
			inc hl
			ld (rd_dst), hl
			jr rd_rl_lp
rd_rl_end:
			ld hl, (rd_dst)
			ld (hl), 0
			ret

; Exists(name): True / False
rd_exists:
			call rd_find
			ld hl, 0
			ret c
			dec hl
			ret

; Size(name): its length, a Long written at (rd_res) (or a status)
rd_size:
			call rd_find
			ld de, (rd_res)
			jr c, rd_sz_status
			ld hl, rd_ent + 15
			ld bc, 3
			ldir
			xor a
			ld (de), a
			ret
rd_sz_status:
			ex de, hl
			ld (hl), e
			inc hl
			ld (hl), d
			inc hl
			ld (hl), #FF
			inc hl
			ld (hl), #FF
			ret

; DirEntry(n): the n-th file's name ("NAME.EXT", 1 = the first) into the
; string at (rd_res); "" past the last (or no disc)
rd_dirent:
			ld hl, (rd_res)
			ld (hl), 0
			dec hl
			ld a, (hl)
			ld (rd_cap), a
			call rd_mount
			ret nz
			ld de, (rd_a1)
			ld a, d
			or a
			ret nz
			ld a, e
			or a
			ret z
			ld b, a
			ld a, (rd_slots)
			push bc
			call rd_sel				; (rd_sel uses BC)
			pop bc
			ld hl, (rd_dir)
rd_de_lp:
			push hl
			ld de, 11
			add hl, de
			bit 7, (hl)
			pop hl
			jr nz, rd_de_done		; past the last
			dec b
			jr z, rd_de_got
			ld de, RD_ENTRY
			add hl, de
			jr rd_de_lp
rd_de_got:
			ld de, rd_name			; (a copy: the ROM goes out before the string is written)
			ld bc, 11
			ldir
			call rd_unsel
			ld hl, rd_name
			ld de, (rd_res)
			ld b, 8
			call rd_de_part
			ld a, (rd_name + 8)
			cp ' '
			jr z, rd_de_end
			ld a, '.'
			call rd_de_put
			ld hl, rd_name + 8
			ld b, 3
			call rd_de_part
rd_de_end:
			xor a
			ld (de), a
			ret
rd_de_done:
			jp rd_unsel
rd_de_part:							; B letters at HL (up to a space) to DE
			ld a, (hl)
			cp ' '
			ret z
			call rd_de_put
			inc hl
			djnz rd_de_part
			ret
rd_de_put:							; A to DE if the string has room
			push af
			ld a, (rd_cap)
			or a
			jr z, rd_dp_full
			dec a
			ld (rd_cap), a
			pop af
			ld (de), a
			inc de
			ret
rd_dp_full:
			pop af
			ret

; SelectVolume("R"): OK when a disc is there, else NotFound
rd_selvol:
			call rd_mount
			ld hl, RD_NOTFOUND
			ret nz
			ld hl, 0
			ret

; rd_ns - NotSupported (a method the disc can't do)
rd_ns:
			ld hl, RD_NOTSUP
			ret

;## kw_bssinit ntc_data ntc_plat_memtop ntc_plat_screen kw_stop @shared
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  it (from ntc_end, not in its file). Check they fit under the platform's top (and 256 bytes
;  under the real stack when that is above them), then clear them. Too big: a message, the
;  program stops.
kw_bssinit:
			pop hl
			ld (ntc_bsa), hl
			pop bc
			ld (ntc_bsz), bc
			ld (ntc_bsp), sp
			ld sp, (ntc_csp)
			add hl, bc				; HL = their end
			ex de, hl
			call ntc_plat_memtop	; HL = the platform's top
			or a
			sbc hl, de
			jr c, ntc_bs_big
			ld hl, (ntc_csp)		; the real stack, when above them
			ld bc, (ntc_bsa)
			or a
			sbc hl, bc
			jr c, ntc_bs_ok
			ld hl, (ntc_csp)
			ld bc, -256
			add hl, bc
			or a
			sbc hl, de
			jr c, ntc_bs_big
ntc_bs_ok:
			ld bc, (ntc_bsz)
			ld a, b
			or c
			jr z, ntc_bs_done
			ld hl, (ntc_bsa)
			ld (hl), 0
			dec bc
			ld a, b
			or c
			jr z, ntc_bs_done
			ld d, h
			ld e, l
			inc de
			ldir
ntc_bs_done:
			ld sp, (ntc_bsp)
			ret
ntc_bs_big:
			ld hl, ntc_bstxt
ntc_bs_pl:
			ld a, (hl)
			or a
			jr z, ntc_bs_stop
			inc hl
			ld (ntc_bsa), hl
			ld ix, ntc_bs_pn
			jp ntc_plat_putc
ntc_bs_pn:
			ld hl, (ntc_bsa)
			jr ntc_bs_pl
ntc_bs_stop:
			ld ix, kw_stop
			jp ntc_plat_newline
ntc_bsa:		dw 0
ntc_bsz:		dw 0
ntc_bsp:		dw 0
ntc_bstxt:		db "Not enough memory for the arrays", 0

;## ntc_plat_data
ntc_curx:		db 0			; cursor column (0 based) - kept here for Tab
ntc_cury:		db 0			; cursor row (0 based)
ntc_scols:		db 40			; columns in this mode
ntc_smode:		db 1			; screen mode (for the Graphics class)
ntc_fwa:		db 0			; ntc_fwcall: A on return
ntc_fwwrap:		db 0			; 1 = the last character made the firmware wrap
ntc_irqset:		db 0			; 1 = the firmware's fast ticker calls ntc_fwevt
ntc_irqv:		dw 0			; interrupt classes' counting (ntc_isl_tick), 0 = none
ntc_irqix:		dw 0
NTC_FWBLK	equ #A5F0		; the fast ticker's event block (central 32K, below the firmware)
ntc_fwtop:		dw #A600		; the top of free RAM (#A5F0 with the fast ticker's block)
ntc_fwblk:		dw NTC_FWBLK		; the fast ticker's event block: lower (and the top with it) when the ROMs
								; started take more RAM than AMSDOS's #A700-#ABFF (Option RomEnable)

;## ntc_plat_fw ntc_plat_data ntc_data @shared
; ------------------------------------------------------------
; ntc_fwcall - IY = firmware address; A, BC, DE, HL go in and come
; back as the firmware leaves them (A also in ntc_fwa, carry kept).
; IX is kept. Interrupts are on during the call.
; ------------------------------------------------------------
ntc_fwcall:
			ld (ntc_hostix), ix
			ld (ntc_ip), sp
			ld sp, (ntc_csp)
			ei
			call ntc_fwjp
			di
			ld sp, (ntc_ip)
			ld (ntc_fwa), a
			ld ix, (ntc_hostix)
			jp (ix)
ntc_fwjp:
			jp (iy)

;## ntc_plat_screen ntc_plat_fw ntc_plat_data ntc_data
; ntc_plat_putc - A = character: TXT OUTPUT. The firmware wraps by itself after
; the last column, so only the column is counted here; a new line straight after
; that wrap is left out (it would leave an empty line)
ntc_plat_putc:
			ld iy, #BB5A			; TXT OUTPUT
			ld (ntc_pclink), ix
			ld ix, ntc_pc_back
			jp ntc_fwcall
ntc_pc_back:
			ld ix, (ntc_pclink)
			xor a
			ld (ntc_fwwrap), a
			ld a, (ntc_scols)
			ld b, a
			ld a, (ntc_curx)
			inc a
			ld (ntc_curx), a
			cp b
			jr nz, ntc_pc_done
			xor a				; the firmware wrapped to the next line
			ld (ntc_curx), a
			inc a
			ld (ntc_fwwrap), a
ntc_pc_done:
			jp (ix)

; ntc_plat_newline - CR LF (the firmware scrolls); nothing straight after a wrap
ntc_plat_newline:
			ld a, (ntc_fwwrap)
			or a
			jr z, ntc_nl_go
			xor a
			ld (ntc_fwwrap), a
			jp (ix)
ntc_nl_go:
			ld (ntc_pclink), ix
			ld a, 13
			ld iy, #BB5A
			ld ix, ntc_nl_lf
			jp ntc_fwcall
ntc_nl_lf:
			ld a, 10
			ld iy, #BB5A
			ld ix, ntc_nl_done
			jp ntc_fwcall
ntc_nl_done:
			xor a
			ld (ntc_curx), a
			ld a, (ntc_cury)
			inc a
			cp 25
			jr c, ntc_nl_row
			ld a, 24
ntc_nl_row:
			ld (ntc_cury), a
			ld ix, (ntc_pclink)
			jp (ix)

ntc_pclink:		dw 0

;## ntc_plat_mode @unit ntc_plat_screen ntc_plat_fw ntc_plat_data ntc_data
; ntc_plat_mode - A = mode 0-2 (3 = 2): SCR SET MODE (clears)
ntc_plat_mode:
			cp 3
			jr c, ntc_md_ok
			ld a, 2
ntc_md_ok:
			ld b, 20
			or a
			jr z, ntc_md_set
			ld b, 40
			cp 1
			jr z, ntc_md_set
			ld b, 80
ntc_md_set:
			ld (ntc_smode), a
			ld c, a
			ld a, b
			ld (ntc_scols), a
			xor a
			ld (ntc_fwwrap), a
			ld (ntc_curx), a
			ld (ntc_cury), a
			ld a, c
			ld iy, #BC0E			; SCR SET MODE
			jp ntc_fwcall

;## ntc_plat_ticks ntc_plat_fw
; ntc_plat_ticks - HL = the firmware's 1/300 s clock (KL TIME PLEASE, low word)
ntc_plat_ticks:
			ld iy, #BD0D
			jp ntc_fwcall

;## ntc_plat_exit ntc_plat_data ntc_plat_fw
ntc_plat_exit:
			ld bc, #7FC0		; RAM setting back to plain (a Memory page may be in #4000)
			out (c), c
			ld a, (ntc_irqset)	; the fast ticker out of the firmware's list
			or a
			jr z, ntc_ex_done
			xor a
			ld (ntc_irqset), a
			ld (ntc_irqix), ix
			ld hl, (ntc_fwblk)
			ld iy, #BCE6		; KL DEL FAST TICKER
			ld ix, ntc_ex_back
			jp ntc_fwcall
ntc_ex_back:
			ld ix, (ntc_irqix)
ntc_ex_done:
			jp (ix)

;## ntc_plat_fs ntc_data ntc_buf2k @shared
FS_NOTFOUND	equ -2
FS_TOOBIG	equ -8
FS_FAILED	equ -9
FS_BADNAME	equ -4
fs_a1:			dw 0
fs_a2:			dw 0
fs_a3:			dw 0
fs_res:			dw 0
fs_sp:			dw 0
fs_esp:			dw 0
fs_six:			dw 0
fs_siy:			dw 0
fs_len:			dw 0
fs_nostore:		db 0
fs_hmode:		db 0			; 0 no file open, 1 reading, 2 writing (Open)
fs_init:		db 0			; 1 = checked: is AMSDOS running?
fs_dos:			db 0			; 1 = a DOS is there (|DISC found)
fs_devd:		db 0			; the device in use: 0 tape, 1 disc
fs_n_tape:		db "TAPE", 0
fs_n_disc:		db "DISC", 0
fs_n_all:		db "TAPE,DISC", 0
fs_c_tape:		db "TAP", "E" + #80
fs_c_disc:		db "DIS", "C" + #80
fs_vol:			ds 9			; the volume in use ("" = not known)
fs_vols:		ds 145			; the volumes that worked, "A,C,M" (up to 16 of up to 8 letters)
fs_tmpn:		ds 9			; a volume name, capitals
fs_rsxn:		ds 17			; a command name (last letter + #80), up to 16 letters
fs_buf			equ ntc_buf		; the 2K buffer CAS IN OPEN / CAS OUT OPEN want (shared with Memory.Copy)
			ASSERT NTC_BUFSIZE >= 2048, "FileSystem needs the whole 2K buffer (Option Buffer's size)"
			ASSERT ntc_free <= #A600, "FileSystem on cpcfw: the program and its arrays must end below #A600 (AMSDOS's RAM)"

fs_go0:
			ld a, 1
			ld (fs_nostore), a
			jr fs_gostart
fs_go:
			xor a
			ld (fs_nostore), a
fs_gostart:
			ld (fs_sp), sp
			ld sp, (ntc_csp)
			ld (fs_six), ix
			ld (fs_siy), iy
			ei
			ld (fs_esp), sp
			call fs_jphl
fs_back:
			di
			ld ix, (fs_six)
			ld iy, (fs_siy)
			ld a, (fs_nostore)
			or a
			jr nz, fs_gone
			ex de, hl
			ld hl, (fs_res)
			ld (hl), e
			inc hl
			ld (hl), d
fs_gone:
			ld sp, (fs_sp)
			ret
fs_jphl:
			jp (hl)
fs_err:
			ld sp, (fs_esp)
			jr fs_back

; fs_start - the first file call: is AMSDOS running? (no ROMs are started here:
; Option RomEnable does that in the start code)
fs_start:
			ld a, (fs_init)
			or a
			ret nz
			inc a
			ld (fs_init), a
			ld a, (#BC77)
			cp #DF				; a far call: AMSDOS has the cassette calls
			jr nz, fs_st_find	; not running (RUN" dropped it), or |TAPE: tape
			ld a, 1
			ld (fs_devd), a
		IF NTC_ROMENABLE
			ld hl, fs_n_a1		; started by the program: AMSDOS starts on drive A
			call fs_addvol
			ld hl, fs_n_a1
			ld de, fs_vol
			ld bc, 2
			ldir
		ENDIF
fs_st_find:
			ld hl, fs_c_disc
			call #BCD4			; KL FIND COMMAND: is |DISC there?
			ld a, 1
			jr c, fs_st_dos
			xor a
fs_st_dos:
			ld (fs_dos), a
			ret
fs_n_a1:		db "A", 0

; fs_rsx - HL = an AMSDOS command's name (last letter + #80): run it, no arguments.
; Not there goes to fs_err (NotFound)
fs_rsx:
			call #BCD4			; KL FIND COMMAND: HL = address, C = ROM
			jr nc, fs_rx_none
			xor a				; no arguments
			ld ix, fs_rx_none	; (the argument list: none)
			call #001B			; KL FAR PCALL
			ret
fs_rx_none:
			ld hl, FS_NOTFOUND
			jp fs_err

; fs_strout - HL = text (0 ended) into the String result at (fs_res), cut at its size
fs_strout:
			ex de, hl
			ld hl, (fs_res)
			dec hl
			ld b, (hl)			; the capacity
			inc hl
			ex de, hl
fs_so_lp:
			ld a, (hl)
			or a
			jr z, fs_so_end
			ld c, a
			ld a, b
			or a
			jr z, fs_so_end
			ld a, c
			ld (de), a
			inc hl
			inc de
			dec b
			jr fs_so_lp
fs_so_end:
			xor a
			ld (de), a
			ret

; fs_same - HL = the program's text, DE = a name in capitals: Z when the same (any case)
fs_same:
			ld a, (hl)
			call fs_up
			ld c, a
			ld a, (de)
			cp c
			ret nz
			or a
			ret z
			inc hl
			inc de
			jr fs_same

; fs_volname - HL = text: a volume name (up to 8 letters, a ':' after it is allowed) into
; fs_tmpn (capitals) and fs_rsxn (last letter + #80). NZ: not a name
fs_volname:
			ld de, fs_tmpn
			ld b, 0
fs_vn_lp:
			ld a, (hl)
			or a
			jr z, fs_vn_end
			cp ':'
			jr z, fs_vn_colon
			call fs_up
			ld (de), a
			inc hl
			inc de
			inc b
			ld a, b
			cp 9
			jr c, fs_vn_lp
			or a				; too long: NZ (A = 9)
			ret
fs_vn_colon:
			inc hl
			ld a, (hl)
			or a
			ret nz				; something after the ':'
fs_vn_end:
			xor a
			ld (de), a
			ld a, b
			or a
			jr z, fs_vn_bad
			ld hl, fs_tmpn
			ld de, fs_rsxn
			ld c, b
			ld b, 0
			ldir
			dec de
			ld a, (de)
			or #80
			ld (de), a
			xor a				; Z: a name
			ret
fs_vn_bad:
			inc a				; NZ
			ret

; fs_addvol - HL = a volume name (capitals, 0 ended): into fs_vols if not there and room
fs_addvol:
			ld (fs_len), hl		; (the name)
			ld de, fs_vols
fs_av_entry:
			ld a, (de)
			or a
			jr z, fs_av_add		; the end of the list: not there
			ld hl, (fs_len)
fs_av_cmp:
			ld a, (de)
			cp ','
			jr z, fs_av_sep
			or a
			jr z, fs_av_sep
			cp (hl)
			jr nz, fs_av_skip
			inc hl
			inc de
			jr fs_av_cmp
fs_av_sep:
			ld a, (hl)			; the entry ended: the same if the name ended too
			or a
			ret z
fs_av_skip:
			ld a, (de)			; on to the next entry
			or a
			jr z, fs_av_add
			inc de
			cp ','
			jr nz, fs_av_skip
			jr fs_av_entry
fs_av_add:
			ld hl, (fs_len)		; DE = the 0 at the end: room for "," + name + 0?
			push hl
			ld b, 0
fs_av_len:
			ld a, (hl)
			or a
			jr z, fs_av_room
			inc hl
			inc b
			jr fs_av_len
fs_av_room:
			pop hl
			push hl
			ld hl, fs_vols + 145 - 2
			or a
			sbc hl, de
			ld a, h
			or a
			jr nz, fs_av_ok		; plenty
			ld a, l
			cp b
			jr nc, fs_av_ok
			pop hl
			ret					; full: not added
fs_av_ok:
			pop hl
			ld a, e
			cp low fs_vols
			jr nz, fs_av_comma
			ld a, d
			cp high fs_vols
			jr z, fs_av_copy
fs_av_comma:
			ld a, ','
			ld (de), a
			inc de
fs_av_copy:
			ld a, (hl)
			ld (de), a
			inc hl
			inc de
			or a
			jr nz, fs_av_copy
			ret

; fs_namevol - after a Load / Save that worked: a volume in its name ("C:NAME") joins the list
fs_namevol:
			ld hl, (fs_a1)
			ld b, 9
fs_nv_lp:
			ld a, (hl)
			or a
			ret z
			cp ':'
			jr z, fs_nv_found
			inc hl
			djnz fs_nv_lp
			ret
fs_nv_found:
			ld a, 9
			sub b
			ret z				; ":NAME": no volume
			ld hl, (fs_a1)
			ld de, fs_tmpn
			ld c, a
			ld b, 0
fs_nv_cp:
			ld a, (hl)
			call fs_up
			ld (de), a
			inc hl
			inc de
			dec c
			jr nz, fs_nv_cp
			xor a
			ld (de), a
			ld hl, fs_tmpn
			jp fs_addvol

; Devices(): "TAPE,DISC" with a DOS, "TAPE" without
fs_devices:
			call fs_start
			ld hl, fs_n_all
			ld a, (fs_dos)
			or a
			jp nz, fs_strout
			ld hl, fs_n_tape
			jp fs_strout

; CurrentDevice(): "TAPE" or "DISC"
fs_curdev:
			call fs_start
			ld hl, fs_n_tape
			ld a, (fs_devd)
			or a
			jp z, fs_strout
			ld hl, fs_n_disc
			jp fs_strout

; SelectDevice(name): "TAPE" or "DISC" (any case). OK, NotFound
fs_select:
			call fs_start
			ld hl, (fs_a1)
			ld de, fs_n_tape
			call fs_same
			jr z, fs_se_tape
			ld hl, (fs_a1)
			ld de, fs_n_disc
			call fs_same
			jr nz, fs_se_bad
			ld a, (fs_dos)
			or a
			jr z, fs_se_bad		; no DOS: no disc
			ld hl, fs_c_disc
			call fs_rsx
			ld a, 1
			jr fs_se_done
fs_se_tape:
			ld a, (fs_dos)
			or a
			jr z, fs_se_t2		; no DOS: tape anyway
			ld hl, fs_c_tape
			call fs_rsx
fs_se_t2:
			xor a
fs_se_done:
			ld (fs_devd), a
			ld hl, 0
			ret
fs_se_bad:
			ld hl, FS_NOTFOUND
			ret

; Volumes(): the volumes that worked so far ("A,C")
fs_volumes:
			call fs_start
			ld hl, fs_vols
			jp fs_strout

; CurrentVolume(): the volume last selected ("" = not known)
fs_curvol:
			call fs_start
			ld hl, fs_vol
			jp fs_strout

; SelectVolume(name): runs the DOS's command of that name (|A, |B, |C, |M ... whatever
; the DOS has). OK, NotFound (no such command). It joins Volumes()
fs_selvol:
			call fs_start
			ld hl, (fs_a1)
			call fs_volname
			jr nz, fs_se_bad
			ld hl, fs_rsxn
			call fs_rsx
			ld hl, fs_tmpn
			ld de, fs_vol
			ld bc, 9
			ldir
			ld hl, fs_tmpn
			call fs_addvol
			ld hl, 0
			ret

; Command(name): run a ROM's command (an RSX: |NAME) with no arguments - AMSDOS, M4,
; a utility ROM ... OK, NotFound (no ROM has it). Up to 16 letters
fs_command:
			call fs_start
			ld hl, (fs_a1)
			ld de, fs_rsxn
			ld b, 0
fs_cm_lp:
			ld a, (hl)
			or a
			jr z, fs_cm_end
			call fs_up
			ld (de), a
			inc hl
			inc de
			inc b
			ld a, b
			cp 17
			jr c, fs_cm_lp
fs_cm_bad:
			ld hl, FS_NOTFOUND
			ret
fs_cm_end:
			ld a, b
			or a
			jr z, fs_cm_bad
			dec de
			ld a, (de)
			or #80
			ld (de), a
			ld hl, fs_rsxn
			call fs_rsx
			ld hl, 0
			ret

fs_up:
			cp 'a'
			ret c
			cp 'z' + 1
			ret nc
			sub 32
			ret

; fs_name - B = length of the name at (fs_a1), HL = the name; an empty or too long name goes to fs_err
fs_name:
			ld hl, (fs_a1)
			ld b, 0
fs_nm_lp:
			ld a, (hl)
			or a
			jr z, fs_nm_end
			inc hl
			inc b
			ld a, b
			cp 17
			jr c, fs_nm_lp
fs_nm_bad:
			ld hl, FS_BADNAME
			jp fs_err
fs_nm_end:
			ld a, b
			or a
			jr z, fs_nm_bad
			ld hl, (fs_a1)
			ret

; Load(name, addr, maxlen): bytes loaded (the file's length), or a status.
; A file longer than maxlen is not loaded: FS_TOOBIG
fs_load:
			call fs_start
			ld a, (fs_hmode)	; the buffer is the open file's
			or a
			ld hl, FS_FAILED
			jp nz, fs_err
			call fs_name
			ld de, fs_buf
			call #BC77			; CAS IN OPEN: BC = length, carry = ok
			jr c, fs_ld_open
			ld hl, FS_NOTFOUND
			jp fs_err
fs_ld_open:
			ld (fs_len), bc
			ld hl, (fs_a3)
			or a
			sbc hl, bc
			jr nc, fs_ld_fits
			call #BC7D			; CAS IN ABANDON
			ld hl, FS_TOOBIG
			jp fs_err
fs_ld_fits:
			ld hl, (fs_a2)
			call #BC83			; CAS IN DIRECT
			jr c, fs_ld_read
			call #BC7D
			ld hl, FS_FAILED
			jp fs_err
fs_ld_read:
			call #BC7A			; CAS IN CLOSE
			ld hl, (fs_len)
			push hl
			call fs_namevol
			pop hl
			ret

; Save(name, addr, len): a binary file (type 2, BASIC can LOAD it back). 0 or a status
fs_save:
			call fs_start
			ld a, (fs_hmode)	; the buffer is the open file's
			or a
			ld hl, FS_FAILED
			jp nz, fs_err
			call fs_name
			ld de, fs_buf
			call #BC8C			; CAS OUT OPEN
			jr c, fs_sv_open
			ld hl, FS_FAILED
			jp fs_err
fs_sv_open:
			ld hl, (fs_a2)
			ld de, (fs_a3)
			ld bc, 0			; entry address: none
			ld a, 2				; binary
			call #BC98			; CAS OUT DIRECT
			jr c, fs_sv_done
			call #BC92			; CAS OUT ABANDON
			ld hl, FS_FAILED
			jp fs_err
fs_sv_done:
			call #BC8F			; CAS OUT CLOSE
			ld hl, FS_FAILED
			ret nc
			call fs_namevol
			ld hl, 0
			ret

;## ntc_plat_fsseq ntc_plat_fs @shared
; ---- one open file (handle 1), through CAS IN CHAR / CAS OUT CHAR: read a
; file (any type) byte by byte, or write a new text file (type ASCII, as
; BASIC's OPENOUT / PRINT #9 make it). The 2K buffer is the one Load / Save
; use, so Load and Save are refused while a file is open.
FS_NOHANDLE	equ -5
FS_BADHANDLE	equ -6
FS_EOFST	equ -7
FS_BADMODE	equ -11
FS_NOTSUP	equ -1
fs_ptr:			dw 0
fs_cnt:			db 0
fs_cap:			db 0

; Open(name, mode): 1, or a status. ForUpdate: NotSupported
fs_open:
			call fs_start
			ld a, (fs_hmode)
			or a
			ld hl, FS_NOHANDLE
			ret nz
			ld hl, (fs_a2)
			ld a, h
			or a
			jr nz, fs_op_bad
			ld a, l
			cp 4
			jr z, fs_op_in			; ForReadRaw
			cp 3
			ld hl, FS_NOTSUP
			ret z
			jr nc, fs_op_bad
			cp 1
			jr c, fs_op_bad
			jr nz, fs_op_out
fs_op_in:
			ld (fs_raw), a			; 4: raw (a #1A is data), 1: not
			ld hl, fs_pend
			ld (hl), 0
			call fs_name
			ld de, fs_buf
			call #BC77			; CAS IN OPEN
			ld hl, FS_NOTFOUND
			ret nc
			ld (fs_ftype), a
			ld a, 1
			jr fs_op_ok
fs_op_out:
			call fs_name
			ld de, fs_buf
			call #BC8C			; CAS OUT OPEN
			ld hl, FS_FAILED
			ret nc
			ld a, 2
fs_op_ok:
			ld (fs_hmode), a
			ld hl, 1
			ret
fs_op_bad:
			ld hl, FS_BADMODE
			ret

; fs_hchk - (fs_a1) must be handle 1 open for A (1 read, 2 write), else
; fs_err BadHandle
fs_hchk:
			ld hl, (fs_a1)
			dec hl
			ld b, a
			ld a, h
			or l
			jr nz, fs_hc_bad
			ld a, (fs_hmode)
			cp b
			ret z
fs_hc_bad:
			ld hl, FS_BADHANDLE
			jp fs_err

; Close(h): OK, or a status (Failed: the last of a written file didn't go)
fs_closeh:
			ld hl, (fs_a1)
			dec hl
			ld a, h
			or l
			jr nz, fs_hc_bad
			ld a, (fs_hmode)
			or a
			jr z, fs_hc_bad
			ld b, a
			xor a
			ld (fs_hmode), a
			ld a, b
			cp 1
			jr nz, fs_cl_out
			call #BC7A			; CAS IN CLOSE
			jr fs_cl_ok
fs_cl_out:
			call #BC8F			; CAS OUT CLOSE
			ld hl, FS_FAILED
			ret nc
fs_cl_ok:
			call fs_namevol
			ld hl, 0
			ret

; ReadByte(h): 0-255, or EndOfFile
fs_readb:
			ld a, 1
			call fs_hchk
			call fs_inchar
			ld hl, FS_EOFST
			ret nc
			ld l, a
			ld h, 0
			ret

; WriteByte(h, b): OK, or Failed
fs_writeb:
			ld a, 2
			call fs_hchk
			ld a, (fs_a2)
			call #BC95			; CAS OUT CHAR
			ld hl, FS_FAILED
			ret nc
			ld hl, 0
			ret

; fs_inchar - CAS IN CHAR for ReadByte / Read: in a binary file AMSDOS still reports a #1A
; byte as the soft end of file (no carry, A = #1A) and goes on after it: that is the byte
; #1A. The same in any file opened ForReadRaw (a file with no header: AMSDOS calls it ASCII
; text, but the real end is the hard one, #0F, after the last record). Carry = a byte in A;
; no carry = the end (or an error)
fs_inchar:
			ld a, (fs_pend)
			or a
			jr z, fs_ic_rd
			xor a
			ld (fs_pend), a
			ld a, (fs_pendc)		; the byte Eof read ahead
			scf
			ret
fs_ic_rd:
			call #BC80			; CAS IN CHAR
			ret c
			cp #1A
			jr nz, fs_ic_end
			ld a, (fs_raw)
			cp 4
			ld a, #1A
			scf
			ret z				; raw: the byte #1A
			ld a, (fs_ftype)
			and #0E
			cp 2
			ld a, #1A
			scf
			ret z				; binary: the byte #1A
fs_ic_end:
			or a
			ret
fs_raw:			db 0			; Open for reading: 4 = ForReadRaw
fs_pend:		db 0			; 1: Eof read a byte ahead, in fs_pendc
fs_pendc:		db 0
fs_ftype:		db 0			; Open for reading: the file's type (CAS IN OPEN's A: 2 binary, #16 ASCII)

; Read(h, addr, count): bytes read (fewer at the end)
fs_read:
			ld a, 1
			call fs_hchk
			ld hl, (fs_a2)
			ld de, (fs_a3)
			ld bc, 0
fs_rd_lp:
			ld a, d
			or e
			jr z, fs_rd_end
			bit 7, d
			jr nz, fs_rd_end
			push hl
			push de
			push bc
			call fs_inchar
			pop bc
			pop de
			pop hl
			jr nc, fs_rd_end
			ld (hl), a
			inc hl
			inc bc
			dec de
			jr fs_rd_lp
fs_rd_end:
			ld h, b
			ld l, c
			ret

; Write(h, addr, count): count, or Failed
fs_write:
			ld a, 2
			call fs_hchk
			ld hl, (fs_a2)
			ld de, (fs_a3)
fs_wr_lp:
			ld a, d
			or e
			jr z, fs_wr_end
			bit 7, d
			jr nz, fs_wr_end
			ld a, (hl)
			push hl
			push de
			call #BC95			; CAS OUT CHAR
			pop de
			pop hl
			jr nc, fs_wr_fail
			inc hl
			dec de
			jr fs_wr_lp
fs_wr_end:
			ld hl, (fs_a3)
			ret
fs_wr_fail:
			ld hl, FS_FAILED
			ret

; Eof(h): True (-1) when there is nothing more to read (or h is not a file being read)
fs_eof:
			ld hl, (fs_a1)
			dec hl
			ld a, h
			or l
			jr nz, fs_ef_yes
			ld a, (fs_hmode)
			cp 1
			jr nz, fs_ef_yes
			call fs_inchar			; a byte read ahead (CAS TEST EOF at a #1A - a soft end
			ld hl, -1			; of file - loses bytes: the #1A and more)
			ret nc
			ld (fs_pendc), a
			ld a, 1
			ld (fs_pend), a
			ld hl, 0
			ret
fs_ef_yes:
			ld hl, -1
			ret

; ReadLine(h): the next line (up to LF; CR dropped), "" at the end
fs_readln:
			ld hl, (fs_res)
			ld (hl), 0
			dec hl
			ld a, (hl)
			ld (fs_cap), a			; the result's capacity
			inc hl
			ld (fs_ptr), hl
			xor a
			ld (fs_cnt), a
			ld a, 1
			call fs_hchk
fs_rl_lp:
			call fs_inchar
			jr nc, fs_rl_end
			cp 10
			jr z, fs_rl_end
			cp 13
			jr z, fs_rl_lp
			ld c, a
			ld a, (fs_cap)
			ld hl, fs_cnt
			cp (hl)
			jr z, fs_rl_lp			; full: the rest of the line is dropped
			inc (hl)
			ld hl, (fs_ptr)
			ld (hl), c
			inc hl
			ld (fs_ptr), hl
			jr fs_rl_lp
fs_rl_end:
			ld hl, (fs_ptr)
			ld (hl), 0
			ret

; WriteLine(h, s): the text and CR LF. OK, or Failed
fs_writeln:
			ld a, 2
			call fs_hchk
			ld hl, (fs_a2)
fs_wl_lp:
			ld a, (hl)
			or a
			jr z, fs_wl_end
			push hl
			call #BC95			; CAS OUT CHAR
			pop hl
			jp nc, fs_wr_fail
			inc hl
			jr fs_wl_lp
fs_wl_end:
			ld a, 13
			call #BC95
			jp nc, fs_wr_fail
			ld a, 10
			call #BC95
			jp nc, fs_wr_fail
			ld hl, 0
			ret

;## ntc_plat_memtop ntc_plat_data
; ntc_plat_memtop - HL = the first byte the Memory class's Small heap must not
; use: #A600 (the firmware's and AMSDOS's RAM is above), #A5F0 when the fast
; ticker's event block is there (Interrupt, interrupt classes). Called on the
; real stack (call / ret).
ntc_plat_memtop:
			ld hl, (ntc_fwtop)
			ret

;## ntc_plat_romsel @shared @ramonly
; rd_sel - A = a slot: that ROM in at #C000 (KL ROM SELECT: the upper ROM on,
; the firmware knows). rd_unsel - what was in before back (KL ROM DESELECT).
; From RAM only (@ramonly: never in the keyword ROM). Keep DE, HL (rd_unsel
; also AF)
rd_old:			dw 0
rd_sel:
			push hl
			push de
			ld c, a
			call #B90F			; KL ROM SELECT: B / C = the state and ROM before
			ld (rd_old), bc
			pop de
			pop hl
			ret
rd_unsel:
			push af
			push hl
			push de
			ld bc, (rd_old)
			call #B918			; KL ROM DESELECT
			pop de
			pop hl
			pop af
			ret

;## ntc_plat_rdroute ntc_plat_fs ntc_romdisc @shared @ramonly
; rd_route ... - a FileSystem method's way to the ROMDISC (volume R): HL =
; the fs_ routine, DE = the rd_ one, fs_a1 ... fs_res set. The rd_ routine
; is picked (fs_a1 .. fs_res copied to rd_a1 .. rd_res) when
;   rd_route / rd_route0:   the name at (fs_a1) is "R:..." - or has no volume
;                           and the volume in use is R
;   rd_routeh / rd_routeh0: fs_a1 is handle 2 (the ROMDISC's open file)
;   rd_routev:              the name is "R" (or "R:")
; then fs_go (the ..0 ones: fs_go0). Runs on the thread: no call, no push.
rd_rtf:			db 0
rd_rtd:			dw 0
rd_routev:
			ld a, 4
			jr rd_rt
rd_routeh0:
			ld a, 3
			jr rd_rt
rd_routeh:
			ld a, 2
			jr rd_rt
rd_route0:
			ld a, 1
			jr rd_rt
rd_route:
			xor a
rd_rt:
			ld (rd_rtf), a
			ld (rd_rtd), de
			bit 1, a
			jr nz, rd_rt_h
			bit 2, a
			jr nz, rd_rt_v
			ex de, hl				; DE = the fs_ routine
			ld hl, (fs_a1)
			inc hl
			ld a, (hl)
			dec hl
			cp ':'
			jr nz, rd_rt_cur
			ld a, (hl)
			or #20
			cp 'r'
			jr z, rd_rt_rd
			jr rd_rt_fs
rd_rt_cur:							; no volume in the name: the one in use
			ld a, (fs_vol)
			cp 'R'
			jr nz, rd_rt_fs
			ld a, (fs_vol + 1)
			or a
			jr z, rd_rt_rd
rd_rt_fs:
			ex de, hl				; HL = the fs_ routine
			jr rd_rt_go
rd_rt_h:
			ex de, hl
			ld hl, (fs_a1)
			ld a, h
			or a
			jr nz, rd_rt_fs
			ld a, l
			cp 2
			jr z, rd_rt_rd
			jr rd_rt_fs
rd_rt_v:
			ex de, hl
			ld hl, (fs_a1)
			ld a, (hl)
			or #20
			cp 'r'
			jr nz, rd_rt_fs
			inc hl
			ld a, (hl)
			or a
			jr z, rd_rt_rd
			cp ':'
			jr nz, rd_rt_fs
			inc hl
			ld a, (hl)
			or a
			jr nz, rd_rt_fs
rd_rt_rd:
			ld hl, (fs_a1)
			ld (rd_a1), hl
			ld hl, (fs_a2)
			ld (rd_a2), hl
			ld hl, (fs_a3)
			ld (rd_a3), hl
			ld hl, (fs_res)
			ld (rd_res), hl
			ld hl, (rd_rtd)
rd_rt_go:
			ld a, (rd_rtf)
			rra
			jp c, fs_go0
			jp fs_go

; rd_fsvol - SelectVolume "R": the disc there, then R is the volume in use
; (names without one go to the disc) and joins Volumes()
rd_fsvol:
			call rd_selvol
			ld a, h
			or l
			ret nz
			ld hl, rd_vr
			ld de, fs_vol
			ld bc, 2
			ldir
			ld hl, rd_vr
			call fs_addvol
			ld hl, 0
			ret
rd_vr:			db "R", 0

; rd_nsl - NotSupported as a Long at (fs_res) (Size on a volume that can't)
rd_nsl:
			ld hl, (fs_res)
			ld a, #FF
			ld (hl), a
			inc hl
			ld (hl), a
			inc hl
			ld (hl), a
			inc hl
			ld (hl), a
			ret


ntc_end:				; the end of the program (and of its file)
; arrays: after the program, not in its file - kw_bssinit checks they fit and clears them
ntc_bssfrom	equ ntc_end
ntc_bss		equ ntc_bssfrom
arr_mem		equ ntc_bss + 0		; 4096 bytes
arr_v		equ ntc_bss + 4096		; 16 bytes
arr_stk		equ ntc_bss + 4112		; 32 bytes
arr_disp		equ ntc_bss + 4144		; 2048 bytes
arr_kp		equ ntc_bss + 6192		; 16 bytes
arr_keymap		equ ntc_bss + 6208		; 32 bytes
ntc_bss_size	equ 6240
ntc_free	equ ntc_bss + ntc_bss_size	; the first free byte (heap, Memory tables)
ntc_memtab	equ ntc_free		; the Memory class's tables
			SAVEAMSDOS "CHIP8.BIN", ntc_start, ntc_end - ntc_start, ntc_start
